from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    # Step 1: Remove any spaces in the input string
    paren_string = paren_string.replace(" ", "")

    # Step 2: Iterate through the input string and identify the start and end indices of each group of nested parentheses
    groups = []
    start = 0
    stack = []

    for i, char in enumerate(paren_string):
        if char == '(':
            stack.append(i)
        elif char == ')':
            if stack:
                start = stack.pop()
                groups.append(paren_string[start:i+1])

    # Step 3: Extract each group of nested parentheses using the start and end indices
    # Step 4: Check if each extracted group is balanced
    balanced_groups = []
    for group in groups:
        stack = []
        is_balanced = True
        for char in group:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack:
                    is_balanced = False
                    break
                stack.pop()
        if is_balanced and not stack:
            balanced_groups.append(group)

    # Step 5: Return the list of separated groups
    return balanced_groups

# Test the function with the provided example
print(separate_paren_groups('( ) (( )) (( )( ))'))  # Output: ['()', '(())', '(()())']

